#!/usr/bin/env node
// Programs required by skills and agents: shows what is missing and installs if Settings allow Claude.
//   node scripts/needs.mjs [name ...] [--install] [--json]
//
// Without names checks the entire hub; with names checks only those skills/agents (and their dependencies).
// --install installs missing tools ONLY if settings.json has dependencies.claudeMayInstall = true; otherwise
// exits with code 3 and executes nothing (Claude must prompt user). Only tools listed in dependencies.json
// are installed: the command is generated by deps.mjs (winget/brew/npm/uv + package), never by a skill.
import { HUB_ROOT, commandExists, parseArgs } from './lib/util.mjs';
import { ensureIndex } from './lib/scan.mjs';
import { installPlan, loadDependencies, missingSkillCommands, runPlan, validateDependencies } from './lib/deps.mjs';
import { availableManagers, runCommand } from './lib/machine.mjs';
import { readSettings } from './lib/settings.mjs';
import { tFor } from './lib/i18n.mjs';

const t = tFor(HUB_ROOT);
const { flags, positional } = parseArgs(process.argv.slice(2), { boolean: ['install', 'json', 'help'] });
if (flags.help) {
  console.log(t('needs.usage'));
  process.exit(0);
}
const json = Boolean(flags.json);
const say = (...a) => {
  if (!json) console.log(...a);
};

const deps = loadDependencies(HUB_ROOT);
const depErrors = validateDependencies(deps);
if (depErrors.length) {
  console.error(t('needs.depErrors', { list: depErrors.join('\n  - ') }));
  process.exit(2);
}
const allowed = readSettings(HUB_ROOT)['dependencies.claudeMayInstall'];
const index = ensureIndex(HUB_ROOT);

// ---- targets (with declared dependencies)
const all = [...index.skills, ...index.agents];
const byId = new Map(all.map((e) => [e.id, e]));
const unknown = [];
let scope = index;
if (positional.length) {
  const picked = new Set();
  const visit = (id) => {
    if (picked.has(id) || !byId.has(id)) return;
    picked.add(id);
    byId.get(id).dependsOn.forEach(visit);
  };
  for (const n of positional) {
    const id = /^(skill|agent):/.test(n) ? n : byId.has(`skill:${n}`) ? `skill:${n}` : `agent:${n}`;
    if (byId.has(id)) visit(id);
    else unknown.push(n);
  }
  const ents = [...picked].map((id) => byId.get(id));
  scope = { skills: ents.filter((e) => e.kind === 'skill'), agents: ents.filter((e) => e.kind === 'agent') };
}

const managers = availableManagers();
const missing = missingSkillCommands(scope).map((m) => {
  const prov = deps.commandProviders[m.command];
  const plan = prov ? installPlan(prov.install, null, { managers }) : null;
  return { ...m, name: prov?.name ?? m.command, known: Boolean(prov), plan };
});

const report = {
  allowed,
  unknownItems: unknown,
  missing: missing.map(({ plan, ...m }) => ({ ...m, installCommand: plan?.auto ? plan.display : null, reason: plan && !plan.auto ? plan.reason : m.known ? null : t('needs.notInDependencies') })),
  installed: [],
  failed: [],
};

say(t('needs.claudeMayInstall', { allowed: allowed ? t('needs.yes') : t('needs.no') }));
for (const n of unknown) say(t('needs.unknownItem', { name: n }));
if (!missing.length) say(t('needs.noMissing'));
for (const m of report.missing) {
  const action = m.installCommand ? `  → ${m.installCommand}` : `  (${m.reason})`;
  say(t('needs.missingRow', { cmd: m.command.padEnd(12), req: m.requiredBy.join(', '), action }));
}

let code = missing.length ? 1 : 0;
if (flags.install && missing.length) {
  if (!allowed) {
    say(t('needs.installRefused'));
    report.refused = true;
    code = 3;
  } else {
    // con --json l'output del gestore non deve mescolarsi al JSON
    const runner = json ? (cmd, args) => runCommand(cmd, args, { timeout: 30 * 60 * 1000 }) : undefined;
    for (const m of missing) {
      if (!m.plan?.auto) continue;
      say(t('needs.installing', { name: m.name, cmd: m.plan.display }));
      const r = runPlan(m.plan, runner);
      if (r.ok) {
        report.installed.push(m.command);
        say(commandExists(m.command) ? t('needs.installedOk', { name: m.name }) : t('needs.installedReopenTerminal', { name: m.name }));
      } else {
        report.failed.push({ command: m.command, error: r.error });
        say(t('needs.installFailed', { name: m.name, error: r.error }));
      }
    }
    const left = missing.filter((m) => !commandExists(m.command));
    code = left.length ? 1 : 0;
  }
}

if (json) console.log(JSON.stringify(report, null, 2));
process.exit(code);
